package com.quincaisoft.commerce.infrastructure;
import jakarta.persistence.*;import java.util.*;import java.io.Serializable;
@Entity @Table(name="commerce_listing") @IdClass(Listing.Key.class) public class Listing {@Id @Column(name="tenant_id") public UUID tenantId;@Id @Column(name="company_id") public UUID companyId;@Id public UUID id;@Column(name="branch_id") public UUID branchId;@Column(name="store_id") public UUID storeId;@Column(name="product_id") public UUID productId;public String title;public String description;public String unit;@Column(name="price_xaf") public long priceXaf;public boolean published;@Version public long version;public static class Key implements Serializable{public UUID tenantId,companyId,id;public Key(){}public Key(UUID t,UUID c,UUID i){tenantId=t;companyId=c;id=i;}public boolean equals(Object o){return o instanceof Key k&&Objects.equals(tenantId,k.tenantId)&&Objects.equals(companyId,k.companyId)&&Objects.equals(id,k.id);}public int hashCode(){return Objects.hash(tenantId,companyId,id);}}}
